// src/packageDiff/outputs/jsonOutput.ts
class JsonOutput {
  format(result) {
    const data = {
      schema_version: 1,
      has_uncommitted_changes: result.hasUncommittedChanges,
      diffs: result.diffs.map((diff) => ({
        filename: diff.filename,
        type: diff.type,
        from_commit: diff.fromCommit,
        to_commit: diff.toCommit,
        is_new: diff.isNew,
        workspace_name: diff.workspaceName,
        changes: diff.changes.map((change) => ({
          name: change.name,
          type: change.type,
          from: change.from,
          to: change.to,
          status: change.status,
          semver: change.semver,
          release_count: change.releaseCount,
          from_section: change.fromSection,
          to_section: change.toSection
        }))
      }))
    };
    return JSON.stringify(data, null, 2);
  }
}

// src/packageDiff/outputs/markdownOutput.ts
class MarkdownOutput {
  showEmpty;
  constructor(showEmpty = false) {
    this.showEmpty = showEmpty;
  }
  format(result) {
    if (!result.hasAnyChanges()) {
      return this.showEmpty ? `# Dependency Changes

No dependency changes detected.` : "No dependency changes detected.";
    }
    const lines = [];
    lines.push("# Dependency Changes");
    lines.push("");
    if (result.hasUncommittedChanges) {
      lines.push("> **Note:** Showing uncommitted changes");
      lines.push("");
    }
    for (const diff of result.diffs) {
      lines.push(...this.formatDiff(diff));
    }
    return lines.join(`
`);
  }
  formatDiff(diff) {
    if (!diff.hasChanges() && !this.showEmpty) {
      return [];
    }
    const lines = [];
    const workspaceSuffix = diff.type === "package-json" /* PackageJson */ && diff.workspaceName ? ` (${diff.workspaceName})` : "";
    lines.push(`## ${diff.filename}${workspaceSuffix}`);
    if (diff.isNew) {
      lines.push("*File created*");
    } else {
      const fromCommit = diff.fromCommit ? diff.fromCommit.slice(0, 7) : "unknown";
      const toCommit = diff.toCommit ? diff.toCommit.slice(0, 7) : "uncommitted";
      lines.push(`*Changes from \`${fromCommit}\` to \`${toCommit}\`*`);
    }
    lines.push("");
    if (!diff.hasChanges()) {
      lines.push("No dependency changes detected.");
      lines.push("");
      return lines;
    }
    const added = diff.getAddedPackages();
    if (added.length) {
      lines.push("### Added");
      lines.push("");
      lines.push("| Package | Version |");
      lines.push("|---------|---------|");
      for (const change of added) {
        lines.push(`| **${change.name}** | \`${change.to}\` |`);
      }
      lines.push("");
    }
    const removed = diff.getRemovedPackages();
    if (removed.length) {
      lines.push("### Removed");
      lines.push("");
      lines.push("| Package | Version |");
      lines.push("|---------|---------|");
      for (const change of removed) {
        lines.push(`| **${change.name}** | \`${change.from}\` |`);
      }
      lines.push("");
    }
    const updated = diff.getUpdatedPackages();
    if (updated.length) {
      lines.push("### Updated");
      lines.push("");
      lines.push("| Package | From | To | Change | Releases |");
      lines.push("|---------|------|----|--------|----------|");
      for (const change of updated) {
        const semver11 = this.getSemverEmoji(change.semver);
        const releaseText = this.getReleaseText(change.releaseCount ?? null);
        lines.push(`| **${change.name}** | \`${change.from}\` | \`${change.to}\` | ${semver11} | ${releaseText} |`);
      }
      lines.push("");
    }
    const downgraded = diff.getDowngradedPackages();
    if (downgraded.length) {
      lines.push("### Downgraded");
      lines.push("");
      lines.push("| Package | From | To | Change | Releases |");
      lines.push("|---------|------|----|--------|----------|");
      for (const change of downgraded) {
        const semver11 = this.getSemverEmoji(change.semver);
        const releaseText = this.getReleaseText(change.releaseCount ?? null);
        lines.push(`| **${change.name}** | \`${change.from}\` | \`${change.to}\` | ${semver11} | ${releaseText} |`);
      }
      lines.push("");
    }
    const changed = diff.getChangedPackages();
    if (changed.length) {
      lines.push("### Changed (non-semver)");
      lines.push("");
      lines.push("| Package | From | To | From section | To section |");
      lines.push("|---------|------|----|--------------|------------|");
      for (const change of changed) {
        lines.push(`| **${change.name}** | \`${change.from}\` | \`${change.to}\` | \`${change.fromSection ?? ""}\` | \`${change.toSection ?? ""}\` |`);
      }
      lines.push("");
    }
    return lines;
  }
  getSemverEmoji(semver11) {
    if (!semver11)
      return "";
    switch (semver11) {
      case "major" /* Major */:
        return "\uD83D\uDD34 Major";
      case "minor" /* Minor */:
        return "\uD83D\uDFE1 Minor";
      case "patch" /* Patch */:
        return "\uD83D\uDFE2 Patch";
    }
  }
  getReleaseText(releaseCount) {
    if (!releaseCount || releaseCount === 0) {
      return "";
    }
    return String(releaseCount);
  }
}

// src/packageDiff/helpers/commandErrorHandler.ts
class CommandErrorHandler {
  static handle(error, format, exitCode = 1) {
    const message = error.message;
    if (format === "json") {
      process.stdout.write(JSON.stringify({ error: message }, null, 2) + `
`);
    } else {
      process.stderr.write(`Error: ${message}
`);
    }
    return exitCode;
  }
  static handleQuiet(error, quiet, exitCode = 2) {
    if (!quiet) {
      process.stderr.write(`Error: ${error.message}
`);
    }
    return exitCode;
  }
}

// src/packageDiff/commands/analyseCommand.ts
function createAnalyseCommand({ cache, diffCalculator }) {
  const command = new Command("analyse").description("See what's changed in your project's dependencies").helpOption("-h, --help", "Display help for command").option("--fail-on <rules>", "Exit with code 1 if any change matches the rule(s) (comma-separated: any, major, minor, patch, added, removed, updated, downgraded, changed)");
  addSharedOptions(command);
  command.action(async () => {
    const options = command.opts();
    const ignoreLast = Boolean(options.ignoreLast);
    const format = String(options.format ?? "text");
    const showEmpty = Boolean(options.showEmpty);
    const noCache = Boolean(options.cache === false || options.noCache);
    const fromCommit = options.from ?? null;
    const toCommit = options.to ?? null;
    const includeTypes = options.include;
    const excludeTypes = options.exclude;
    const sectionsOption = options.sections;
    const explain = Boolean(options.explain);
    const failOn = options.failOn;
    if ((fromCommit || toCommit) && ignoreLast) {
      process.stderr.write(`Cannot use --ignore-last with --from or --to options
`);
      process.exitCode = 1;
      return;
    }
    if (includeTypes && excludeTypes) {
      process.stderr.write(`Cannot use both --include and --exclude options
`);
      process.exitCode = 1;
      return;
    }
    try {
      if (noCache) {
        cache.disableCache();
      }
      const { types, error } = parsePackageManagerTypes(includeTypes, excludeTypes);
      if (!types) {
        process.stderr.write(`${error}
`);
        process.exitCode = 1;
        return;
      }
      const { sections, error: sectionsError } = parsePackageJsonSections(sectionsOption);
      if (sectionsError) {
        process.stderr.write(`${sectionsError}
`);
        process.exitCode = 1;
        return;
      }
      diffCalculator.packageJsonOnlySections(sections);
      for (const type of types) {
        diffCalculator.for(type);
      }
      if (showEmpty) {
        diffCalculator.includeEmptyDiffsWhenNoChanges();
      }
      if (ignoreLast) {
        diffCalculator.ignoreLastCommit();
      }
      if (fromCommit !== null) {
        diffCalculator.fromCommitRef(fromCommit);
      }
      if (toCommit !== null) {
        diffCalculator.toCommitRef(toCommit);
      }
      const showProgress = shouldShowProgress(format, options);
      if (showProgress) {
        const { total, generator } = await diffCalculator.run(true);
        if (total > 0) {
          await showProgressBar(total, generator);
        } else {
          for await (const _ of generator) {}
        }
        const result = diffCalculator.getResult();
        const formatter = getFormatter(format, process.stdout.isTTY ?? false, showEmpty);
        process.stdout.write(formatter.format(result) + `
`);
        if (explain) {
          writeExplain(result);
        }
        if (failOn) {
          if (shouldFailOn(result, failOn)) {
            process.exitCode = 1;
          }
        }
      } else {
        const result = await diffCalculator.run(false);
        const formatter = getFormatter(format, process.stdout.isTTY ?? false, showEmpty);
        process.stdout.write(formatter.format(result) + `
`);
        if (explain) {
          writeExplain(result);
        }
        if (failOn) {
          if (shouldFailOn(result, failOn)) {
            process.exitCode = 1;
          }
        }
      }
    } catch (error) {
      const exitCode = CommandErrorHandler.handle(error, format);
      process.exitCode = exitCode;
    }
  });
  return command;
}
function getFormatter(format, useAnsi, showEmpty) {
  switch (format) {
    case "json":
      return new JsonOutput;
    case "markdown":
      return new MarkdownOutput(showEmpty);
    default:
      return new TextOutput(useAnsi, showEmpty);
  }
}
function shouldShowProgress(format, options) {
  const noProgress = Boolean(options.noProgress);
  return format === "text" && process.stdout.isTTY === true && !noProgress;
}
async function showProgressBar(total, generator) {
  let processed = 0;
  const start = Date.now();
  let progressStarted = false;
  for await (const _ of generator) {
    processed += 1;
    const elapsed = Date.now() - start;
    if (!progressStarted && elapsed >= 1000) {
      progressStarted = true;
    }
    if (progressStarted) {
      const percent = Math.min(100, Math.round(processed / total * 100));
      process.stdout.write(`\rAnalysing changes.. ${processed}/${total} (${percent}%)`);
    }
  }
  if (progressStarted) {
    process.stdout.write(`
`);
  }
}
function writeExplain(result) {
  for (const diff of result.diffs) {
    const from = diff.fromCommit ?? "unknown";
    const to = diff.toCommit ?? "working tree";
    process.stderr.write(`[explain] ${diff.filename}: ${from} -> ${to}
`);
  }
}
function shouldFailOn(result, failOn) {
  const rules = new Set(failOn.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean));
  if (rules.size === 0)
    return false;
  if (rules.has("none"))
    return false;
  const changes = result.getAllChanges();
  if (rules.has("any")) {
    return changes.length > 0;
  }
  for (const change of changes) {
    if (rules.has(change.status)) {
      return true;
    }
    if (change.semver && rules.has(change.semver)) {
      return true;
    }
  }
  return false;
}

